import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), q = nextInt();
        HashSet<Long> houses = new HashSet<>(4 * n + 4);
        long[] xs = new long[n];
        for (int i = 0; i < n; i++) { xs[i] = nextLong(); houses.add(xs[i]); }
        // a block starts at every house without a left neighbor
        long segments = 0;
        for (long x : xs) if (!houses.contains(x - 1)) segments++;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long v = nextLong();
            int left = houses.contains(v - 1) ? 1 : 0, right = houses.contains(v + 1) ? 1 : 0;
            segments += left + right - 1; // split (+1), shrink (0) or vanish (-1)
            houses.remove(v);
            sb.append(segments).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"strconv"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, q := readInt(), readInt()
	houses := make(map[int]bool, n)
	xs := make([]int, n)
	for i := range xs {
		xs[i] = readInt()
		houses[xs[i]] = true
	}
	// a block starts at every house without a left neighbor
	segments := 0
	for _, x := range xs {
		if !houses[x-1] {
			segments++
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	for i := 0; i < q; i++ {
		v := readInt()
		// split (+1), shrink (0) or vanish (-1)
		if houses[v-1] {
			segments++
		}
		if houses[v+1] {
			segments++
		}
		segments--
		delete(houses, v)
		w.WriteString(strconv.Itoa(segments))
		w.WriteByte('\n')
	}
}
